def handover(read, loaded, rejected, duplicate_ids, statuses):
    allowed = {"paid", "refunded", "failed"}
    return [
        "reconciled: " + ("yes" if read == loaded + rejected else "NO"),
        f"duplicates: {duplicate_ids}",
        "statuses ok: " + ("yes" if all(s in allowed for s in statuses) else "NO"),
    ]

for line in handover(120, 118, 2, 0, ["paid", "failed"]):
    print(line)
print("--")
for line in handover(120, 117, 2, 1, ["paid", "pending"]):
    print(line)
